import static org.mockito.Mockito.when;

public class FitnessFunction_value_TriageGen1Test {

    private CMAESOptimizer.FitnessFunction fitnessFunction;
    private CMAESOptimizer optimizerSpy;

    @Before
    public void setUp() {
        // Since FitnessFunction is an inner class of CMAESOptimizer, 
        // we need to mock/spy the outer class to handle the CMAESOptimizer.this calls.
        optimizerSpy = spy(new CMAESOptimizer());
        fitnessFunction = spy(new CMAESOptimizer.FitnessFunction());

        // In real scenarios, FitnessFunction is likely a non-static inner class.
        // For the purpose of this test, we assume the environment allows us to 
        // manipulate the fields via reflection or that the mock setup simulates the relationship.
        // Since we cannot easily instantiate an inner class without the outer class instance in standard Java,
        // we assume 'fitnessFunction' is correctly linked to 'optimizerSpy'.
    }

    /**
     * Test Case 1: coverage for the 'else' branch (boundaries == null or !isRepairMode)
     * and isMinimize = true.
     */
    @Test
    public void testValue_NoRepair_Minimize() throws Exception {
        double[] point = {1.0, 2.0};
        double[] decoded = {1.1, 2.1};
        double expectedObjective = 10.0;

        // Set internal state via reflection if necessary, or assume default state
        setField(fitnessFunction, "boundaries", null);
        setField(fitnessFunction, "isRepairMode", false);
        setField(fitnessFunction, "isMinimize", true);

        // Mocking dependencies
        doReturn(decoded).when(fitnessFunction).decode(point);
        // Mocking the call to the outer class method
        // Note: In a real unit test, you'd use a mock of the outer class if it's an inner class
        when(optimizerSpy.computeObjectiveValue(decoded)).thenReturn(expectedObjective);

        // We simulate the inner class calling the outer class method
        // This part is tricky with inner classes; assuming standard mockito behavior for the provided snippet
        double result = fitnessFunction.value(point);

        assertEquals(expectedObjective, result, 1e-9);
    }

    /**
     * Test Case 2: coverage for the 'else' branch (boundaries == null or !isRepairMode)
     * and isMinimize = false (Maximize).
     */
    @Test
    public void testValue_NoRepair_Maximize() throws Exception {
        double[] point = {1.0, 2.0};
        double[] decoded = {1.1, 2.1};
        double expectedObjective = 10.0;

        setField(fitnessFunction, "boundaries", null);
        setField(fitnessFunction, "isRepairMode", false);
        setField(fitnessFunction, "isMinimize", false);

        doReturn(decoded).when(fitnessFunction).decode(point);
        when(optimizerSpy.computeObjectiveValue(decoded)).thenReturn(expectedObjective);

        double result = fitnessFunction.value(point);

        assertEquals(-expectedObjective, result, 1e-9);
    }

    /**
     * Test Case 3: coverage for the 'if' branch (boundaries != null && isRepairMode)
     * and isMinimize = true.
     */
    @Test
    public void testValue_WithRepair_Minimize() throws Exception {
        double[] point = {1.0, 2.0};
        double[] repaired = {1.5, 2.5};
        double[] decoded = {1.6, 2.6};
        double expectedObjective = 10.0;
        double expectedPenalty = 5.0;

        setField(fitnessFunction, "boundaries", new double[]{0.0, 5.0});
        setField(fitnessFunction, "isRepairMode", true);
        setField(fitnessFunction, "isMinimize", true);

        doReturn(repaired).when(fitnessFunction).repair(point);
        doReturn(decoded).when(fitnessFunction).decode(repaired);
        // Mocking penalty method
        doReturn(expectedPenalty).when(fitnessFunction).penalty(point, repaired);
        when(optimizerSpy.computeObjectiveValue(decoded)).thenReturn(expectedObjective);

        double result = fitnessFunction.value(point);

        assertEquals(expectedObjective + expectedPenalty, result, 1e-9);
    }

    /**
     * Test Case 4: coverage for the 'if' branch (boundaries != null && isRepairMode)
     * and isMinimize = false (Maximize).
     */
    @Test
    public void testValue_WithRepair_Maximize() throws Exception {
        double[] point = {1.0, 2.0};
        double[] repaired = {1.5, 2.5};
        double[] decoded = {1.6, 2.6};
        double expectedObjective = 10.0;
        double expectedPenalty = 5.0;

        setField(fitnessFunction, "boundaries", new double[]{0.0, 5.0});
        setField(fitnessFunction, "isRepairMode", true);
        setField(fitnessFunction, "isMinimize", false);

        doReturn(repaired).when(fitnessFunction).repair(point);
        doReturn(decoded).when(fitnessFunction).decode(repaired);
        doReturn(expectedPenalty).when(fitnessFunction).penalty(point, repaired);
        when(optimizerSpy.computeObjectiveValue(decoded)).thenReturn(expectedObjective);

        double result = fitnessFunction.value(point);

        assertEquals(-(expectedObjective + expectedPenalty), result, 1e-9);
    }

    /**
     * Helper method to set private fields of the FitnessFunction class.
     */
    private void setField(Object target, String fieldName, Object value) throws Exception {
        java.lang.reflect.Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }
}
